update public.learning_paths
set
  title = 'Islam',
  goal = 'Islam',
  summary = 'Study Islam academically, respectfully, and critically through texts, rituals, histories, communities, objects, law, theology, and modern public life. The course situates early Islam in late antiquity, then covers the Qur''an and tafsir, Muhammad and the early community, hadith and legal schools, ritual and ethical practice, Sunni and Shi''i traditions, theology and philosophy, Sufism, empires and institutions, knowledge and material culture, gender and family, global and diaspora Islam, modern reform and state power, and contemporary public scholarship.',
  data = $isljson${"slug": "islam", "title": "Islam", "description": "Study Islam academically, respectfully, and critically through texts, rituals, histories, communities, objects, law, theology, and modern public life. The course situates early Islam in late antiquity, then covers the Qur'an and tafsir, Muhammad and the early community, hadith and legal schools, ritual and ethical practice, Sunni and Shi'i traditions, theology and philosophy, Sufism, empires and institutions, knowledge and material culture, gender and family, global and diaspora Islam, modern reform and state power, and contemporary public scholarship.", "topics": [{"id": "1f63433b-ad5c-4285-9e97-5bd40687a20f", "type": "topic", "title": "Studying Islam: Method, Sources, Lived Religion, and Public Representation", "description": "Students begin by learning how to study Islam academically, respectfully, and critically through texts, rituals, histories, communities, objects, law, theology, and modern public life.", "children": [{"id": "fe7bb80c-3a45-4d88-89da-03eb864f5913", "type": "subtopic", "title": "Academic study of Islam", "children": [{"id": "9921199f-2f13-40eb-9e7b-796318782a30", "type": "concept", "title": "Religious studies, history, anthropology, law, theology, textual studies, and area studies"}, {"id": "210e89a1-9fde-4eb4-a37a-26b7bac21c8e", "type": "concept", "title": "Insider/outsider perspectives and respectful critical distance"}, {"id": "12b4ad21-6581-4c88-99d2-78b0b949a479", "type": "concept", "title": "Avoiding essentialism, Islamophobia, apologetics, and reductionism"}], "description": "Students learn to distinguish scholarly analysis from devotional, polemical, and media-driven accounts."}, {"id": "cb19afb8-6bc5-4940-a7fa-2be3ab0e1507", "type": "subtopic", "title": "Sources and evidence", "children": [{"id": "fef6977c-21b2-4a90-ab4c-9943853bc08a", "type": "concept", "title": "Qur'an, hadith, sira, tafsir, law manuals, poetry, art, architecture, oral histories, and ethnography"}, {"id": "cc63ceea-6c71-43b3-97fb-1e96cf331c41", "type": "concept", "title": "Primary and secondary sources, translation, authorship, and genre"}, {"id": "7e75da75-7110-4478-8672-17598b1e8e92", "type": "concept", "title": "Manuscripts, archives, digital tools, and material culture"}], "description": "The point is to understand how different sources answer different questions."}, {"id": "5ca382eb-9937-41ad-a12c-7c4ebcddd136", "type": "subtopic", "title": "Lived Islam and public Islam", "children": [{"id": "eba141ff-7f25-4022-aa19-e4a755eb33a2", "type": "concept", "title": "Mosques, homes, shrines, schools, courts, media, festivals, and online spaces"}, {"id": "3b765d81-3850-41f7-af7c-ee483a909183", "type": "concept", "title": "Race, ethnicity, language, class, gender, and migration"}, {"id": "050e0e38-0ecc-4347-9618-1ef43dafd9b7", "type": "concept", "title": "Public representation, museums, journalism, policy, and interfaith contexts"}], "description": "Students see Islam as practiced by diverse communities rather than as a single abstract system."}]}, {"id": "31ca74eb-85d2-4b6d-9124-49e66a0e0b60", "type": "topic", "title": "Arabia, Late Antiquity, and the Religious World Before Islam", "description": "This module situates the emergence of Islam within Arabian, Jewish, Christian, Zoroastrian, tribal, imperial, commercial, and poetic worlds of late antiquity.", "children": [{"id": "49498839-8984-4a84-addb-d6528af4d389", "type": "subtopic", "title": "Late antique setting", "children": [{"id": "30e6544d-4cf9-49bb-aa46-3e299b6c90ee", "type": "concept", "title": "Byzantine, Sasanian, Jewish, Christian, Zoroastrian, and Arabian contexts"}, {"id": "af0f801b-5d70-487c-9366-217399d0a7e8", "type": "concept", "title": "Trade routes, pilgrimage, tribal politics, poetry, and sanctuary"}, {"id": "04996cae-1846-40d7-b210-afa2f749aa47", "type": "concept", "title": "Monotheism, prophecy, scripture, and apocalyptic expectation"}], "description": "Students place early Islam in a wider regional and imperial world."}, {"id": "b66df472-8ccd-4f5c-86f8-52d94ac4a079", "type": "subtopic", "title": "Arabian society", "children": [{"id": "d7d7ceb1-e88b-44e5-adeb-adae0644de82", "type": "concept", "title": "Mecca, Medina/Yathrib, clans, kinship, alliances, honor, patronage, and conflict"}, {"id": "2c44cac1-66cd-4128-86c2-a9fcbe081320", "type": "concept", "title": "Ka'ba, pilgrimage, idols, sacred months, and local religious practices"}, {"id": "6d17660a-c430-4001-977f-dcbbd9e6f916", "type": "concept", "title": "Oral culture, poetry, memory, and public speech"}], "description": "The gist is to understand the social world into which the Qur'an was first recited."}, {"id": "60863408-b942-45ff-82e3-dc4138920a86", "type": "subtopic", "title": "Continuity and transformation", "children": [{"id": "b0a026da-cb43-4874-ad96-2fbd36f0e520", "type": "concept", "title": "Revelation, covenant, law, community, charity, worship, and judgment"}, {"id": "b690445f-dfc3-4c72-b09d-c29b8a65abe2", "type": "concept", "title": "Qur'anic engagement with earlier traditions"}, {"id": "94544d1f-5e25-493a-ba86-f8bb71cfb0b1", "type": "concept", "title": "Scholarly debates over origins, context, and evidence"}], "description": "Students learn how Islam both inherited and transformed late antique patterns."}]}, {"id": "ccf4f4ca-d987-4a99-bfa4-49a0c386e9b7", "type": "topic", "title": "Qur'an, Revelation, Recitation, Translation, and Tafsir", "description": "Students study the Qur'an as revelation, recited scripture, Arabic text, interpreted tradition, liturgical presence, and object of modern academic inquiry.", "children": [{"id": "8240b22b-e444-42c2-9c3b-a9d16be5bda0", "type": "subtopic", "title": "Revelation and compilation", "children": [{"id": "11a822ba-758a-49cc-aa28-153cb555d32b", "type": "concept", "title": "Wahy, sura, aya, Meccan/Medinan passages, codification, and canon"}, {"id": "7be21979-8c84-47b7-9322-e5577003a278", "type": "concept", "title": "Recitation, memorization, sound, and liturgy"}, {"id": "ef50a418-9e02-406f-8719-d6b753cda44c", "type": "concept", "title": "Academic debates on chronology, manuscript evidence, and genre"}], "description": "Students learn how Muslims understand the Qur'an as divine speech and how scholars study its formation."}, {"id": "14b741b6-142c-4124-9eed-948db554ea30", "type": "subtopic", "title": "Meaning and interpretation", "children": [{"id": "15f22b49-c653-436c-bc5b-72225027f346", "type": "concept", "title": "Tafsir, asbab al-nuzul, abrogation, Arabic grammar, rhetoric, and legal interpretation"}, {"id": "83dd5f6e-e945-4ed8-90f8-2dd481b6226b", "type": "concept", "title": "Classical, modern, feminist, literary, and thematic readings"}, {"id": "7319b8d4-88e4-4127-8a1a-cca9ab565aab", "type": "concept", "title": "Translation as interpretation and its limits"}], "description": "The point is to see interpretation as a disciplined tradition."}, {"id": "916dd7ee-36a9-47fd-b609-c145691a9c3c", "type": "subtopic", "title": "Major themes", "children": [{"id": "3ea1444f-0d6e-4f34-afe0-9e01645c18a0", "type": "concept", "title": "God, creation, prophecy, mercy, justice, judgment, ethics, community, worship, and scripture"}, {"id": "cc2290b8-ebb9-4cbc-ad74-d774d1c28de4", "type": "concept", "title": "Stories of earlier prophets and communities"}, {"id": "8b8095e8-78d2-45a1-a269-a48d718d6109", "type": "concept", "title": "Social responsibility, charity, family, and accountability"}], "description": "Students identify core Qur'anic concerns and how they shape Muslim life."}]}, {"id": "f48381e9-3fbd-43f7-b862-94ae0d0390a1", "type": "topic", "title": "Muhammad, Sira, Prophethood, and the Early Muslim Community", "description": "This topic examines Muhammad, the Meccan and Medinan communities, prophetic authority, migration, treaties, conflict, leadership, and memory.", "children": [{"id": "425a339c-a0fd-49e8-a5a1-f8b2bb5264dd", "type": "subtopic", "title": "Prophetic biography", "children": [{"id": "3078bbf9-496c-471e-b279-8e64a475363b", "type": "concept", "title": "Birth, first revelation, preaching, persecution, hijra, Medina, treaties, battles, and farewell pilgrimage"}, {"id": "bf83f270-7122-4866-82c1-a6567a108230", "type": "concept", "title": "Sira, maghazi, hadith, and devotional memory"}, {"id": "c89cc7a1-0b08-4c90-a629-17b679527bf4", "type": "concept", "title": "Historical reconstruction and source criticism"}], "description": "Students learn key events and why memory of Muhammad matters."}, {"id": "90d7a65c-b71d-4fad-8c60-4d3c6ccff0b2", "type": "subtopic", "title": "Community formation", "children": [{"id": "0adb96b8-0193-42de-aa69-b71877df28cd", "type": "concept", "title": "Umma, Constitution of Medina, mosque, charity, brotherhood, conflict, diplomacy, and law"}, {"id": "7cfb9a3a-ee7d-4c2e-8c69-4635ddc19b5b", "type": "concept", "title": "Relations with Jewish, Christian, and Arabian groups"}, {"id": "6823094e-c897-4025-a3c4-0918a1db1fa8", "type": "concept", "title": "Leadership, belonging, and communal discipline"}], "description": "The gist is to understand how religious authority became social and political community."}, {"id": "b9655798-5722-443a-8e1c-7d8b4b881af0", "type": "subtopic", "title": "Prophethood and model behavior", "children": [{"id": "96488833-a264-4e49-a1e7-0f19aeb95a3c", "type": "concept", "title": "Sunna, adab, mercy, justice, family life, governance, and ethics"}, {"id": "b2227a7c-5da9-4300-8e95-91f833434fbd", "type": "concept", "title": "Devotional love, praise poetry, and mawlid"}, {"id": "2cac81ce-bb12-4b80-838a-840a495c79ed", "type": "concept", "title": "Modern debates over representation, insult, and public speech"}], "description": "Students study Muhammad as messenger, exemplar, and contested public figure."}]}, {"id": "ae819593-119e-489c-b6aa-80ec45fc43e0", "type": "topic", "title": "Hadith, Sunna, Shari'a, Fiqh, and Legal Schools", "description": "Students learn how Muslims developed norms and legal reasoning through hadith, prophetic practice, juristic interpretation, legal schools, and institutions.", "children": [{"id": "aae6cf24-a97a-4d99-9f02-99bf45f757d9", "type": "subtopic", "title": "Hadith sciences", "children": [{"id": "2c74c2da-6c63-4da1-9a77-23f2388d3e51", "type": "concept", "title": "Isnad, matn, sahih, hasan, da'if, major collections, transmitters, and criticism"}, {"id": "bd2bfd90-355b-48bc-b722-f446de109d46", "type": "concept", "title": "Sunna as normative model"}, {"id": "f1fdcacf-3f0c-418e-bff5-d80e5bc04aeb", "type": "concept", "title": "Modern debates over authenticity and authority"}], "description": "Students learn how reports about Muhammad were collected, classified, and evaluated."}, {"id": "32ef09a6-808b-47b2-8d99-fd1eb961d4f8", "type": "subtopic", "title": "Legal reasoning", "children": [{"id": "3bd3af4a-5a7b-447f-b9a0-ac5d6974cc41", "type": "concept", "title": "Shari'a, fiqh, usul al-fiqh, ijtihad, taqlid, qiyas, ijma, maslaha, and custom"}, {"id": "b2895f61-0af2-4aef-924d-3a692dabe6a5", "type": "concept", "title": "Madhhabs: Hanafi, Maliki, Shafi'i, Hanbali, Ja'fari, and others"}, {"id": "e2ecb3f7-527e-4032-b44f-7819439540a1", "type": "concept", "title": "Fatwa, courts, judges, muftis, and legal pluralism"}], "description": "The point is to understand Islamic law as interpretive reasoning, not a single code."}, {"id": "5666b33e-c307-4832-a281-06bf2f1b2d27", "type": "subtopic", "title": "Law and society", "children": [{"id": "3257be26-917b-4966-8281-e6a2acfba4e5", "type": "concept", "title": "Worship, contracts, marriage, inheritance, food, finance, charity, crime, and public order"}, {"id": "de4a769d-0db8-4220-acab-70978cf1eae7", "type": "concept", "title": "Colonial codification and modern nation-state law"}, {"id": "c08f159f-5537-410d-9c8b-f54af97f2cfc", "type": "concept", "title": "Minority contexts, reform, and comparative legal ethics"}], "description": "Students connect law to everyday ethical and institutional life."}]}, {"id": "6bc6307c-db2b-495d-8a6a-2511e635d9f6", "type": "topic", "title": "Ritual Practice, Devotion, Ethics, and Everyday Muslim Life", "description": "This module studies the five pillars and wider devotional life as embodied practices that shape time, community, moral formation, and belonging.", "children": [{"id": "6521914b-5db6-4c5e-9d01-bfd7a82fca6f", "type": "subtopic", "title": "Five pillars", "children": [{"id": "f83abb87-cfcb-4d3f-b334-ea9a6bc7a807", "type": "concept", "title": "Shahada, salat, zakat, sawm, hajj, intention, purity, prayer direction, and sacred time"}, {"id": "133117b6-c8ce-4ba1-995f-7436829f887f", "type": "concept", "title": "Mosque, congregation, sermon, Ramadan, Eid, and pilgrimage"}, {"id": "54f0758a-0ed9-439e-aba6-070a8092e3a0", "type": "concept", "title": "Ritual obligation, discipline, and social solidarity"}], "description": "Students learn how ritual organizes time, body, community, and accountability."}, {"id": "9de4b1d9-ba3d-4bdb-83c3-e841b471e517", "type": "subtopic", "title": "Devotional life", "children": [{"id": "0c1dfbd0-2af2-4eea-9cf9-a747125b4f69", "type": "concept", "title": "Du'a, dhikr, Qur'an recitation, supplication, blessings, healing, visitation, and life-cycle rituals"}, {"id": "7c89ad9d-ad84-4378-8f82-db0afe9beb90", "type": "concept", "title": "Food, dress, hospitality, etiquette, and family practice"}, {"id": "45013377-bcaa-4a56-b47f-93321de8dbf5", "type": "concept", "title": "Piety movements, youth cultures, and digital devotion"}], "description": "The gist is to see Muslim practice beyond formal obligation."}, {"id": "ea063135-ff54-4bae-81f4-5aec4b03fa30", "type": "subtopic", "title": "Ethical formation", "children": [{"id": "c51e6bff-a9e0-4045-a516-b2497f51ac23", "type": "concept", "title": "Taqwa, ihsan, adab, justice, mercy, humility, generosity, and accountability"}, {"id": "94903c9d-e51d-4798-965c-5b490922e7f3", "type": "concept", "title": "Charity, poverty, environment, conflict, and care"}, {"id": "f338259e-f749-40a6-aa0a-3f0a074549e4", "type": "concept", "title": "Applied cases in medicine, finance, education, and civic life"}], "description": "Students connect ritual practice to moral character and public responsibility."}]}, {"id": "915e128b-f2a8-49ea-8ae1-e8b385613b16", "type": "topic", "title": "Sunni and Shi'i Traditions: Authority, Imamate, Caliphate, Law, and Memory", "description": "Students examine major Sunni and Shi'i histories, institutions, disagreements, shared practices, and the ways authority and memory shape community identity.", "children": [{"id": "e07578eb-ecde-4259-8ad8-5e86dbc11c46", "type": "subtopic", "title": "Early succession and authority", "children": [{"id": "ecc87ea5-daff-42ba-b9ba-f2a30c2e9692", "type": "concept", "title": "Saqifa, caliphate, imamate, Ali, Fatima, Hasan, Husayn, and Karbala"}, {"id": "568f4ab5-b2f4-424c-b34e-75762257aa96", "type": "concept", "title": "Authority, charisma, family of the Prophet, consensus, and community"}, {"id": "77406b1d-0e2d-4811-9c47-3c6c3d134103", "type": "concept", "title": "Memory, mourning, ritual, and identity"}], "description": "Students learn the roots of Sunni/Shi'i differentiation."}, {"id": "33394e91-f998-415a-9e47-f7b941cd081d", "type": "subtopic", "title": "Sunni traditions", "children": [{"id": "8cae930a-41d9-4c63-934b-64570b2d2c21", "type": "concept", "title": "Caliphate, legal schools, theology, hadith, ulama, Sufism, reform, and revival"}, {"id": "5c26a621-864f-4584-8065-5f07800849a0", "type": "concept", "title": "Ash'ari, Maturidi, Hanbali/Athari, and modern movements"}, {"id": "d836bf42-86c1-4b9d-af02-8b1ad36831d1", "type": "concept", "title": "Regional Sunni practices and debates"}], "description": "The point is to understand Sunni diversity and institutions."}, {"id": "40f24ac1-a792-4d47-937a-c8fdc9af129e", "type": "subtopic", "title": "Shi'i traditions", "children": [{"id": "e4c0b8b0-f63a-4fca-9849-d94a56d042cb", "type": "concept", "title": "Twelver, Ismaili, Zaydi, imams, occultation, marja'iyya, taqiyya, and jurisprudence"}, {"id": "70e68384-fb8c-4ddb-9d87-2eb18e74b251", "type": "concept", "title": "Muharram, majlis, pilgrimage, and devotional culture"}, {"id": "fda0960e-f2f4-4129-99e9-5c490db15bc5", "type": "concept", "title": "Iran, Iraq, South Asia, East Africa, and diaspora communities"}], "description": "Students study Shi'i communities on their own terms."}]}, {"id": "d5b79faf-6368-4b94-a9d5-c436f89284e0", "type": "topic", "title": "Islamic Theology and Philosophy: Kalam, Falsafa, Reason, Revelation, and Debate", "description": "This topic introduces theological and philosophical traditions that debated God, scripture, prophecy, causality, ethics, knowledge, and the limits of reason.", "children": [{"id": "5fb661fe-d480-402a-ac60-e9426a4f2f10", "type": "subtopic", "title": "Theological questions", "children": [{"id": "aba65615-2e3e-4933-a3da-bf3a036a28e5", "type": "concept", "title": "Tawhid, divine attributes, free will, predestination, createdness of the Qur'an, and theodicy"}, {"id": "6f6495c6-659c-4d34-9a36-45d622e79d5e", "type": "concept", "title": "Mu'tazili, Ash'ari, Maturidi, Hanbali/Athari, and Shi'i theology"}, {"id": "13ff3132-fb46-406c-be99-dd3ca405ae53", "type": "concept", "title": "Faith, works, sin, salvation, and ethics"}], "description": "Students encounter major debates about God, humans, and moral responsibility."}, {"id": "f6b7be70-b8b0-43c2-b301-abc283284eec", "type": "subtopic", "title": "Philosophy and reason", "children": [{"id": "467be109-444b-4db5-b27d-653988d870e2", "type": "concept", "title": "Falsafa, logic, metaphysics, cosmology, prophecy, soul, and political philosophy"}, {"id": "3e33ee7b-e3e6-473d-b512-c56e48e58db8", "type": "concept", "title": "al-Kindi, al-Farabi, Ibn Sina, al-Ghazali, Ibn Rushd, Suhrawardi, and Mulla Sadra"}, {"id": "08ca82ed-1fb7-45de-bfda-797a78a0d654", "type": "concept", "title": "Reason and revelation as conflict, harmony, or hierarchy"}], "description": "The gist is to see how Muslim thinkers engaged Greek, Persian, and Islamic intellectual worlds."}, {"id": "7722c5f3-5c26-4f7c-a33e-5ddae86966d4", "type": "subtopic", "title": "Debate and transmission", "children": [{"id": "59392000-ef2e-4a23-b19d-2819dd906056", "type": "concept", "title": "Translation movement, Bayt al-Hikma, madrasas, commentaries, disputation, and manuscript culture"}, {"id": "94adbd5f-4c3a-43be-b967-8a8933043e18", "type": "concept", "title": "Connections to Jewish, Christian, and Latin scholastic thought"}, {"id": "2e78ff28-caa2-4aba-aa17-6308885b1889", "type": "concept", "title": "Modern revivals and critiques of philosophy and theology"}], "description": "Students learn how intellectual traditions traveled and changed."}]}, {"id": "ffdfd0ef-67f3-4f13-9dea-f4f5f769a81e", "type": "topic", "title": "Sufism and Islamic Devotional Worlds: Love, Saints, Orders, Poetry, and Practice", "description": "Students study Sufism as disciplined spirituality, ritual practice, literary tradition, social institution, and contested form of Islamic authority.", "children": [{"id": "b1291793-bb59-416b-b9cb-e9270dd1611f", "type": "subtopic", "title": "Sufi concepts", "children": [{"id": "b399b319-47b4-4f76-b15e-7877ad987475", "type": "concept", "title": "Tasawwuf, tariqa, shaykh, murid, dhikr, fana, baqa, baraka, ma'rifa, and love"}, {"id": "bbed3014-b817-4efa-8aba-5f40be79521e", "type": "concept", "title": "Inner purification, discipline, companionship, and ethical refinement"}, {"id": "6253dce5-8e0f-48ee-9324-c19899de0d4b", "type": "concept", "title": "Sufism and shari'a: integration and tension"}], "description": "Students learn the vocabulary of Islamic spirituality."}, {"id": "3eae903e-2f1c-4fef-b5c0-d9bd54428c97", "type": "subtopic", "title": "Orders and practices", "children": [{"id": "c913ba2f-4b4d-45c6-a035-bdd93672be47", "type": "concept", "title": "Qadiriyya, Naqshbandiyya, Chishtiyya, Mevlevi, Tijaniyya, and other orders"}, {"id": "dbcbc12c-87ed-449a-b692-c18a1dc0d8b9", "type": "concept", "title": "Sama, qawwali, whirling, litanies, shrine visitation, and initiation"}, {"id": "ed179e34-bf73-41ef-9b45-026c14f2ebf3", "type": "concept", "title": "Saints, tombs, miracles, pilgrimage, and local authority"}], "description": "The point is to study Sufism as social, ritual, and institutional life."}, {"id": "eeae270e-b8de-478d-ab14-9620f24ae4e2", "type": "subtopic", "title": "Poetry and contestation", "children": [{"id": "0f493dc5-58c6-4b6e-b820-bf49f42ee746", "type": "concept", "title": "Rumi, Hafiz, Ibn Arabi, Attar, Rabia, Yunus Emre, and regional poets"}, {"id": "6c700db2-23ec-4f69-a2fb-c6272144ad15", "type": "concept", "title": "Metaphor, longing, union, annihilation, and divine love"}, {"id": "2f3b5d48-5663-4f02-aa58-1f0678ed53c2", "type": "concept", "title": "Reformist critique, commercialization, translation, and global reception"}], "description": "Students examine Sufism's literary power and modern debates."}]}, {"id": "547dcf2b-d6cb-4821-9b74-f911907d6a88", "type": "topic", "title": "Islamic Empires, Institutions, Urban Life, Trade, and Cultural Exchange", "description": "This module traces Islamic civilization through caliphates, empires, cities, learning institutions, trade networks, and regional cultures.", "children": [{"id": "64eeba77-1c7b-4a42-958b-d518d1bb9410", "type": "subtopic", "title": "Caliphates and empires", "children": [{"id": "3ab04393-9b05-4a0e-a5aa-4c42a67114cf", "type": "concept", "title": "Rashidun, Umayyad, Abbasid, Fatimid, Seljuk, Ottoman, Safavid, Mughal, and regional polities"}, {"id": "d0722e20-f325-43b2-9cc9-a3d2cd3cc697", "type": "concept", "title": "Caliph, sultan, imam, shah, bureaucracy, military slavery, and legitimacy"}, {"id": "fb87d131-daa0-4bca-8e4a-38c23a30a636", "type": "concept", "title": "Dynasty, law, patronage, and religious authority"}], "description": "Students understand political diversity across Islamic history."}, {"id": "5e84baa8-8d7f-42e1-95d8-8bd0c5207421", "type": "subtopic", "title": "Institutions and cities", "children": [{"id": "31922dd9-265a-47bd-b840-a2ac9fb7d901", "type": "concept", "title": "Mosques, madrasas, waqf, courts, markets, hospitals, libraries, caravanserais, and guilds"}, {"id": "d1147797-9ae5-4bf5-a07e-4e1c9eb99d66", "type": "concept", "title": "Baghdad, Cairo, Cordoba, Istanbul, Isfahan, Delhi, Timbuktu, and Samarkand"}, {"id": "95e9d28b-cb06-492e-b587-c713ef392eb1", "type": "concept", "title": "Urban life, scholars, merchants, artisans, and travelers"}], "description": "The gist is to see how Islamic societies organized learning, worship, welfare, and commerce."}, {"id": "1b20ca77-6d24-4a6e-8c96-d9208a26fa47", "type": "subtopic", "title": "Trade and cultural exchange", "children": [{"id": "78ce7451-0f12-467a-9353-3cbe5f6585f5", "type": "concept", "title": "Silk Roads, Indian Ocean, Sahara, Mediterranean, pilgrimage routes, and port cities"}, {"id": "640bc444-79a0-44bc-a671-7d0e51faf71b", "type": "concept", "title": "Arabic, Persian, Turkish, Urdu, Malay, Swahili, and other languages"}, {"id": "fe3b2a22-2f7f-4898-b9c6-dda37bda7c07", "type": "concept", "title": "Conversion, translation, migration, slavery, and cosmopolitanism"}], "description": "Students track Islamic worlds across routes and oceans."}]}, {"id": "96792e34-0a48-4d84-a36a-765c4b98bf1c", "type": "topic", "title": "Knowledge, Education, Science, Art, Literature, and Material Culture", "description": "Students learn how Islamic traditions produced and transmitted knowledge through madrasas, manuscripts, libraries, art, architecture, poetry, music, and objects.", "children": [{"id": "cb25f57f-bbd5-4c09-b577-16fc3d2d8a73", "type": "subtopic", "title": "Education and scholarship", "children": [{"id": "b4b7aafe-ac16-4e65-acc6-cf3309945278", "type": "concept", "title": "Qur'an schools, madrasas, ijaza, commentaries, libraries, paper, and manuscript copying"}, {"id": "9e9f0a57-96ba-461a-8da3-bd0af06a5aa6", "type": "concept", "title": "Ulama, adab, grammar, law, theology, medicine, astronomy, and mathematics"}, {"id": "8f99df78-66b4-4088-a6c7-ac1b6869a089", "type": "concept", "title": "Orality, writing, memorization, and scholarly networks"}], "description": "Students learn how knowledge was preserved and authorized."}, {"id": "1a53b565-0d2e-4d08-b436-e1f1c840af53", "type": "subtopic", "title": "Art and architecture", "children": [{"id": "401f4220-e497-4748-93e7-169a5ca2512b", "type": "concept", "title": "Mosques, mihrab, minbar, dome, minaret, madrasa, palace, garden, and tomb"}, {"id": "ceb1f6c5-7915-4de2-9088-c50f94e4a6ec", "type": "concept", "title": "Calligraphy, geometry, vegetal ornament, ceramics, metalwork, textiles, and manuscripts"}, {"id": "dd99ad5b-8034-4f3f-aa8f-47afdff5b9ac", "type": "concept", "title": "Aniconism debates, visual piety, patronage, and regional styles"}], "description": "The point is to interpret Islamic material culture beyond decorative labels."}, {"id": "6922951b-7a4a-4ff3-a567-1a438be09575", "type": "subtopic", "title": "Literature and performance", "children": [{"id": "e1b67390-d92c-494e-ad16-16f4a7a86580", "type": "concept", "title": "Arabic, Persian, Turkish, Urdu, Malay, and Swahili literary worlds"}, {"id": "4af90f7e-1e17-4da8-a2ea-01cb0535042b", "type": "concept", "title": "Poetry, epics, mirrors for princes, travel writing, hagiography, and devotional song"}, {"id": "c9e7fc94-efd4-427f-84cb-15031e9386d8", "type": "concept", "title": "Aesthetics, ethics, memory, and identity"}], "description": "Students connect religious ideas to stories, music, and public culture."}]}, {"id": "ff6166ee-7824-4732-bea7-e925908e6fb1", "type": "topic", "title": "Gender, Family, Authority, Social Life, and Ethical Debates", "description": "This topic examines gender, kinship, family law, embodiment, modesty, leadership, reform, and contemporary ethical disagreements within Muslim communities.", "children": [{"id": "041e28cd-83dd-44df-bb95-fb06bad319be", "type": "subtopic", "title": "Family and law", "children": [{"id": "d7343183-4247-46b1-9ccd-87c946464c29", "type": "concept", "title": "Marriage, divorce, inheritance, guardianship, kinship, childhood, and domestic economies"}, {"id": "a561d819-ffc1-45ff-b78d-1500fd9fa786", "type": "concept", "title": "Classical jurisprudence and modern legal reform"}, {"id": "089d1eaf-3215-4a1a-af8e-9d5cabe87601", "type": "concept", "title": "Custom, state law, migration, and everyday negotiation"}], "description": "Students study family life through legal, ethical, and social lenses."}, {"id": "144a2670-d490-4d68-b18a-000faa96f16d", "type": "subtopic", "title": "Gender and authority", "children": [{"id": "cb280c82-5bb5-4eea-9355-249b526a4c01", "type": "concept", "title": "Women scholars, transmitters, saints, activists, jurists, teachers, and community leaders"}, {"id": "ee0efa87-97e3-4587-a453-f3ec6723c503", "type": "concept", "title": "Modesty, veiling, embodiment, sexuality, and public space"}, {"id": "84923688-f838-453e-a6a0-030f7e926790", "type": "concept", "title": "Feminist, traditionalist, reformist, and local debates"}], "description": "The gist is to examine how gender shapes religious interpretation and leadership."}, {"id": "2249253e-b0a0-4dd5-81af-ad71fc2b570c", "type": "subtopic", "title": "Contemporary ethics", "children": [{"id": "38ce4e08-fffb-4f00-b996-68ee99f0819b", "type": "concept", "title": "Bioethics, finance, poverty, environment, war and peace, human rights, and pluralism"}, {"id": "75ee00a8-5be0-4cc7-aee7-7ec4f95ba830", "type": "concept", "title": "Islamic ethics, maqasid, maslaha, fatwa, and public reasoning"}, {"id": "d2cb4e79-91ca-47c3-be6d-bc5ed4474521", "type": "concept", "title": "Case-study method and comparative religious ethics"}], "description": "Students practice nuanced analysis of contested issues."}]}, {"id": "ef487755-34c6-4562-896f-e484fd601db7", "type": "topic", "title": "Global Islam: Africa, South Asia, Southeast Asia, Europe, the Americas, and Diaspora", "description": "Students broaden the map beyond the Middle East, studying how Islam tr